@Test
void authorize_doesNotHoldTransactionDuringFraudCall() {
    PaymentRepository repo = mock(PaymentRepository.class);
    FraudClient fraud = mock(FraudClient.class);
    PaymentGateway gateway = mock(PaymentGateway.class);
    when(repo.save(any())).thenAnswer(inv -> inv.getArgument(0));
    when(fraud.score(any())).thenAnswer(inv -> {
        assertFalse(TransactionSynchronizationManager.isActualTransactionActive(),
            "fraud call must not run inside a DB transaction / hold a connection");
        return new FraudVerdict(false, null, 10);
    });
    when(gateway.authorize(any())).thenReturn(new PaymentResult("ref-1"));
    PaymentService svc = new PaymentService(repo, fraud, gateway);
    PaymentResult result = svc.authorize(new AuthorizeRequest("ord_1", new BigDecimal("10.00"), "CAD"));
    assertEquals("ref-1", result.reference());
    verify(repo, atLeast(2)).save(any()); // pending insert + final status/verdict persist, each short tx
}
